// npm run gen: lib/game/render/palette.dart → src/ui/generated/palette.ts. dart:ui does not run in
// the Dart VM, so the colours are read from the source instead of dumped; test/config-sync.test.ts
// fails when the generated file drifts.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const src = fileURLToPath(new URL('../../lib/game/render/palette.dart', import.meta.url));
const dst = fileURLToPath(new URL('../src/ui/generated/palette.ts', import.meta.url));

export function renderPalette(dart: string): string {
  const rows = [...dart.matchAll(/static const (\w+) = Color\(0x([0-9A-Fa-f]{8})\);/g)];
  if (rows.length === 0) throw new Error('no colours found in palette.dart');
  const body = rows.map(([, name, hex]) => `  ${name}: 0x${hex.toUpperCase()},`).join('\n');
  return `// GENERATED by scripts/gen-palette.ts from lib/game/render/palette.dart — do not edit.\n// ARGB, as in Dart's Color(0xAARRGGBB).\nexport const PALETTE = {\n${body}\n} as const;\n`;
}

export const paletteSource = (): string => readFileSync(src, 'utf8');

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(dst, renderPalette(paletteSource()));
  console.log(`wrote ${dst}`);
}
